parameters.query:
select t.office_id, t.provider, t.config, t.cambio_usd_brl,
       public.integration_secret(t.office_id, t.provider) as secret
from public.marketing_import_targets() t;

parameters.jsCode:
// Monta uma requisição por alvo. Janela: ontem e anteontem (a Meta e a OpenAI ajustam o gasto do dia por até 48h).
const dias = Number($env.MARKETING_IMPORT_DAYS || 2);
const fim = new Date(); fim.setUTCHours(0,0,0,0);            // hoje 00:00 UTC (exclusivo)
const ini = new Date(fim); ini.setUTCDate(ini.getUTCDate() - dias);
const iso = d => d.toISOString().slice(0,10);
const out = [];
for (const it of $input.all()) {
  const t = it.json;
  const base = { office_id: t.office_id, provider: t.provider, cambio: Number(t.cambio_usd_brl || 5.5), config: t.config || {} };
  if (t.provider === 'anthropic_admin') {
    out.push({ ...base,
      url: `https://api.anthropic.com/v1/organizations/cost_report?starting_at=${iso(ini)}T00:00:00Z&ending_at=${iso(fim)}T00:00:00Z&bucket_width=1d`,
      headers: { 'x-api-key': t.secret, 'anthropic-version': '2023-06-01', 'User-Agent': 'edem-ia/1.0' } });
  } else if (t.provider === 'openai_admin') {
    out.push({ ...base,
      url: `https://api.openai.com/v1/organization/costs?start_time=${Math.floor(ini.getTime()/1000)}&end_time=${Math.floor(fim.getTime()/1000)}&bucket_width=1d&limit=31`,
      headers: { 'Authorization': `Bearer ${t.secret}` } });
  } else if (t.provider === 'meta_ads') {
    const acct = String(t.config?.ad_account_id || '').startsWith('act_') ? t.config.ad_account_id : `act_${t.config?.ad_account_id}`;
    const ontem = new Date(fim); ontem.setUTCDate(ontem.getUTCDate() - 1);
    const tr = encodeURIComponent(JSON.stringify({ since: iso(ini), until: iso(ontem) }));
    out.push({ ...base,
      url: `https://graph.facebook.com/v21.0/${acct}/insights?fields=spend,date_start,date_stop&time_increment=1&time_range=${tr}&access_token=${encodeURIComponent(t.secret)}`,
      headers: {} });
  }
}
return out.map(j => ({ json: j }));

// Normaliza cada resposta em linhas {office_id, dia, canal, valor_brl, valor_usd, nota}.
const rows = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const req = $('Montar requisições').all()[i].json;
  const body = items[i].json;
  if (!body || body.error) { rows.push({ office_id: req.office_id, provider: req.provider, erro: JSON.stringify(body?.error || body).slice(0,300) }); continue; }
  const porDia = {};
  if (req.provider === 'anthropic_admin') {
    // cost_report: data[].starting_at, results[].amount (string em centavos de USD)
    for (const b of body.data || []) {
      const dia = String(b.starting_at).slice(0,10);
      const cents = (b.results || []).reduce((s, r) => s + Number(r.amount || 0), 0);
      porDia[dia] = (porDia[dia] || 0) + cents / 100;
    }
    for (const [dia, usd] of Object.entries(porDia))
      rows.push({ office_id: req.office_id, dia, canal: 'tokens_anthropic', valor_brl: +(usd * req.cambio).toFixed(2), valor_usd: +usd.toFixed(4), nota: 'Anthropic cost_report' });
  } else if (req.provider === 'openai_admin') {
    // organization/costs: data[].start_time (unix), results[].amount.value (USD)
    for (const b of body.data || []) {
      const dia = new Date(Number(b.start_time) * 1000).toISOString().slice(0,10);
      const usd = (b.results || []).reduce((s, r) => s + Number(r.amount?.value || 0), 0);
      porDia[dia] = (porDia[dia] || 0) + usd;
    }
    for (const [dia, usd] of Object.entries(porDia))
      rows.push({ office_id: req.office_id, dia, canal: 'tokens_openai', valor_brl: +(usd * req.cambio).toFixed(2), valor_usd: +usd.toFixed(4), nota: 'OpenAI organization/costs' });
  } else if (req.provider === 'meta_ads') {
    // insights: data[].spend (moeda da conta), date_start
    const brlConta = String(req.config?.currency || 'BRL').toUpperCase() === 'BRL';
    for (const d of body.data || []) {
      const v = Number(d.spend || 0);
      rows.push({ office_id: req.office_id, dia: d.date_start, canal: 'meta_ads',
                  valor_brl: +((brlConta ? v : v * req.cambio)).toFixed(2), valor_usd: brlConta ? null : +v.toFixed(2), nota: 'Meta Ads insights' });
    }
  }
}
return rows.map(j => ({ json: j }));
